-- State transitions declared for ResourcePermission: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.resource_permissions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'expired'), ('active', 'revoked'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: resource_permissions.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_resource_permissions__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS resource_permissions_status_transition_check ON sapiens.resource_permissions;
CREATE TRIGGER resource_permissions_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.resource_permissions
    FOR EACH ROW EXECUTE FUNCTION sapiens.resource_permissions_status_transition_check();
